_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"21. João e José desejam a morte de Joaquim e ambos, em ocasiões\ndistintas, mas próximas no tempo, sem qualquer conhecimento\nda intenção do outro, ajuste ou mesmo combinação prévia,\natiram contra a vítima. Joaquim morre em decorrência de um dos\ntiros; o outro, conforme exame pericial feito, atingiu a vítima\nsomente de raspão. Todavia, mesmo com a perícia, não restou\nverificada a autoria do tiro que atingiu mortalmente Joaquim.\nNessa hipótese, é correto afirmar que João e José respondem\npor delito de\nA) homicídio doloso na modalidade tentada, com a incidência do\nconcurso de pessoas.\nB) homicídio doloso consumado, sem a incidência do concurso de\npessoas.\nC) homicídio doloso na modalidade tentada, sem a incidência do\nconcurso de pessoas.\nD) homicídio doloso consumado, com a incidência do concurso de\npessoas.\nE) homicídio culposo, sem a incidência do concurso de pessoas.","item_number":21,"source_pages":[7],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/5265fc281b7c7e2f6535c9e222ae499db1e79afbbb1a2ea565320791f72df49a","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Autoria colateral incerta","observed_style":"caso_pratico","explanation":"Sem vínculo subjetivo e sem possibilidade de determinar o tiro fatal, o gabarito C trabalha tentativa para ambos sem concurso de pessoas. Não confundir com autoria cumulativa em que a perícia demonstra contribuição conjunta. Conferir o suporte doutrinário.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","doutrina_pendente"],"primary_evidence":[{"reference":"cp:13","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"f93da1ae56d777386c683c8afb2da2572e69534995e422855eca1c985fb5fd90","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/13","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:14","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"1c58c53b00c1bc7fc70fedb06595f8df2c262043ef650490a2308a4dfcd05356","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/14","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:29","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"8ee1c85803bc6b7fe112bb418ae799c5e2a6d942973069c2d4986b92ab051a5d","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/29","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[7]}}}},{"candidate":"137ce64a77e97ccfeaadb1e64c94938b553fdac4a3c2ea34f40599e747320535","expected_status":"under_review","expected_payload":{"raw_text":"22. Em um dos levantamentos realizados pelo Depen\n(Departamento Penitenciário Nacional), ficou demonstrado\nque, dos crimes previstos no Código Penal, verifica-se que\n72% dos crimes cometidos pelos homens são crimes contra o\npatrimônio, assim como 69% dos perpetrados pelas mulheres.\nConclui-se, portanto, que os delitos contra o patrimônio\nconstituem a maioria dos crimes praticados pela população\ncarcerária brasileira.\nAcerca da jurisprudência do Superior Tribunal de Justiça sobre\no tema, assinale a afirmativa INCORRETA.\nA) O delito de receptação (art. 180 do CP), nas modalidades\ntransportar, conduzir ou ocultar, é crime permanente, cujo\nflagrante perdura enquanto o agente se mantiver na posse do\nbem que sabe ser produto de crime.\nB) O pagamento integral dos débitos oriundos de apropriação\nindébita previdenciária, ainda que efetuado após o\nrecebimento da denúncia, mas antes do trânsito em julgado da\nsentença condenatória, extingue a punibilidade, nos termos do\nart. 9º, §2º, da Lei 10.684/03.\nC) Aplica-se o princípio da insignificância ao crime de apropriação\nindébita previdenciária, quando, na ocasião do delito, o valor\ndo débito com a Previdência Social não ultrapassar o montante\nde R$10.000,00 (dez mil reais), previsto no art. 20 da Lei\n10.522/2002.\nD) O delito de apropriação indébita previdenciária constitui crime\nomissivo próprio, que se perfaz com a mera omissão de\nrecolhimento da contribuição previdenciária dentro do prazo e\ndas formas legais, prescindindo, portanto, do dolo específico.\nE) O crime de extorsão é formal e consuma-se no momento em\nque a violência ou a grave ameaça é exercida,\nindependentemente da obtenção da vantagem indevida.","item_number":22,"source_pages":[7],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"22. Em um dos levantamentos realizados pelo Depen\n(Departamento Penitenciário Nacional), ficou demonstrado\nque, dos crimes previstos no Código Penal, verifica-se que\n72% dos crimes cometidos pelos homens são crimes contra o\npatrimônio, assim como 69% dos perpetrados pelas mulheres.\nConclui-se, portanto, que os delitos contra o patrimônio\nconstituem a maioria dos crimes praticados pela população\ncarcerária brasileira.\nAcerca da jurisprudência do Superior Tribunal de Justiça sobre\no tema, assinale a afirmativa INCORRETA.\nA) O delito de receptação (art. 180 do CP), nas modalidades\ntransportar, conduzir ou ocultar, é crime permanente, cujo\nflagrante perdura enquanto o agente se mantiver na posse do\nbem que sabe ser produto de crime.\nB) O pagamento integral dos débitos oriundos de apropriação\nindébita previdenciária, ainda que efetuado após o\nrecebimento da denúncia, mas antes do trânsito em julgado da\nsentença condenatória, extingue a punibilidade, nos termos do\nart. 9º, §2º, da Lei 10.684/03.\nC) Aplica-se o princípio da insignificância ao crime de apropriação\nindébita previdenciária, quando, na ocasião do delito, o valor\ndo débito com a Previdência Social não ultrapassar o montante\nde R$10.000,00 (dez mil reais), previsto no art. 20 da Lei\n10.522/2002.\nD) O delito de apropriação indébita previdenciária constitui crime\nomissivo próprio, que se perfaz com a mera omissão de\nrecolhimento da contribuição previdenciária dentro do prazo e\ndas formas legais, prescindindo, portanto, do dolo específico.\nE) O crime de extorsão é formal e consuma-se no momento em\nque a violência ou a grave ameaça é exercida,\nindependentemente da obtenção da vantagem indevida.","item_number":22,"source_pages":[7],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/137ce64a77e97ccfeaadb1e64c94938b553fdac4a3c2ea34f40599e747320535","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Crimes patrimoniais e limites da insignificância","observed_style":"jurisprudencia_em_alternativas","explanation":"A resposta histórica C exige conferir o tratamento específico da apropriação indébita previdenciária e os valores invocados. O resumo estatístico do enunciado é histórico; não certifica incidência atual. Todas as cinco teses dependem de precedentes oficiais atuais.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente","dado_estatistico_historico"],"primary_evidence":[{"reference":"cp:168A","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"46c68f5af4f42bcf4dc79463aa184195cf8abbb38a6ff0137c87f7c908583906","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/168A","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:180","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"e4d79eccdc5903093537e6d86b414744acaf1fba3f89b15d24034168cc848c3f","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/180","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[7]}}}},{"candidate":"d2b6b9bf77207af53bea534333e746506c5fc0182df42032c4a228575a6bcd2e","expected_status":"under_review","expected_payload":{"raw_text":"23. De acordo com a legislação, consideram-se hediondos os\ndelitos listados nas alternativas a seguir, À EXCEÇÃO DE\nUMA. Assinale-a.\nA) roubo praticado mediante emprego de explosivo\nB) furto praticado mediante emprego de explosivo\nC) roubo circunstanciado pela restrição da liberdade da vítima\nD) estupro\nE) favorecimento da prostituição de adolescente","item_number":23,"source_pages":[7],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"23. De acordo com a legislação, consideram-se hediondos os\ndelitos listados nas alternativas a seguir, À EXCEÇÃO DE\nUMA. Assinale-a.\nA) roubo praticado mediante emprego de explosivo\nB) furto praticado mediante emprego de explosivo\nC) roubo circunstanciado pela restrição da liberdade da vítima\nD) estupro\nE) favorecimento da prostituição de adolescente","item_number":23,"source_pages":[7],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"A","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/d2b6b9bf77207af53bea534333e746506c5fc0182df42032c4a228575a6bcd2e","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Rol de crimes hediondos","observed_style":"confronto_de_regras","explanation":"A exceção indicada em A depende da redação da Lei 8.072 e da diferença entre arma de fogo, explosivo e furto com explosivo. Alterações posteriores do rol devem ser cotejadas; não certificar a lista de 2021 a partir da memória.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_pendente"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[7]}}}},{"candidate":"d074829c336b1430fe681e2946cf48595792e0851a0ec08b95c0aa9bc81def3e","expected_status":"under_review","expected_payload":{"raw_text":"24. De acordo com o Código Penal, o crime de estupro ocorre\nquando há a seguinte conduta: “constranger alguém, mediante\nviolência ou grave ameaça, a ter conjunção carnal ou a praticar\nou permitir que com ele se pratique outro ato libidinoso” (artigo\n213, caput).\nO Superior Tribunal de Justiça já se manifestou várias vezes\nsobre o crime de estupro.\nAnalisando as afirmativas a seguir, assinale a que está em\nDESACORDO com a jurisprudência do STJ.\nA) Nas hipóteses em que há imprecisão acerca do número exato\nde eventos abusivos à dignidade sexual da vítima, praticados\nem um longo período de tempo, é adequado o aumento de\npena pela continuidade delitiva (art. 71 do CP) em patamar\nsuperior ao mínimo legal.\nB) Nos crimes de estupro ou de atentado violento ao pudor\npraticados com violência presumida, não incide a regra da\ncontinuidade delitiva específica (art. 71, parágrafo único, do\nCP), que condiciona a sua incidência às situações de emprego\nde violência real.\nC) O segredo de justiça previsto no art. 234-B do Código Penal\nabrange apenas a vítima de crimes sexuais, devendo constar\nda autuação somente as iniciais de seu nome.\nD) O avançado estado de embriaguez da vítima, que lhe retire a\ncapacidade de oferecer resistência, é circunstância apta a\nrevelar sua vulnerabilidade e, assim, configurar a prática do\ncrime de estupro previsto no §1º do art. 217-A do Código\nPenal.\nE) Aquele que adere à determinação do comparsa e contribui\npara a consumação do crime de estupro, ainda que não tenha\npraticado a conduta descrita no tipo penal, incide nas penas a\nele cominadas, nos exatos termos do art. 29 do Código Penal.","item_number":24,"source_pages":[8],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"24. De acordo com o Código Penal, o crime de estupro ocorre\nquando há a seguinte conduta: “constranger alguém, mediante\nviolência ou grave ameaça, a ter conjunção carnal ou a praticar\nou permitir que com ele se pratique outro ato libidinoso” (artigo\n213, caput).\nO Superior Tribunal de Justiça já se manifestou várias vezes\nsobre o crime de estupro.\nAnalisando as afirmativas a seguir, assinale a que está em\nDESACORDO com a jurisprudência do STJ.\nA) Nas hipóteses em que há imprecisão acerca do número exato\nde eventos abusivos à dignidade sexual da vítima, praticados\nem um longo período de tempo, é adequado o aumento de\npena pela continuidade delitiva (art. 71 do CP) em patamar\nsuperior ao mínimo legal.\nB) Nos crimes de estupro ou de atentado violento ao pudor\npraticados com violência presumida, não incide a regra da\ncontinuidade delitiva específica (art. 71, parágrafo único, do\nCP), que condiciona a sua incidência às situações de emprego\nde violência real.\nC) O segredo de justiça previsto no art. 234-B do Código Penal\nabrange apenas a vítima de crimes sexuais, devendo constar\nda autuação somente as iniciais de seu nome.\nD) O avançado estado de embriaguez da vítima, que lhe retire a\ncapacidade de oferecer resistência, é circunstância apta a\nrevelar sua vulnerabilidade e, assim, configurar a prática do\ncrime de estupro previsto no §1º do art. 217-A do Código\nPenal.\nE) Aquele que adere à determinação do comparsa e contribui\npara a consumação do crime de estupro, ainda que não tenha\npraticado a conduta descrita no tipo penal, incide nas penas a\nele cominadas, nos exatos termos do art. 29 do Código Penal.","item_number":24,"source_pages":[8],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/d074829c336b1430fe681e2946cf48595792e0851a0ec08b95c0aa9bc81def3e","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Crimes sexuais e segredo de justiça","observed_style":"jurisprudencia_em_alternativas","explanation":"A alternativa C é a tese histórica em desacordo. O segredo do art. 234-B não pode ser reduzido mecanicamente à vítima; houve alterações posteriores no tratamento de dados e consulta de condenados. Verificar cada tese no STJ e o âmbito temporal.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente","legislacao_alterada"],"primary_evidence":[{"reference":"cp:234B","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"55593ea01500f0d4b528163bc0c15692d26d5e47c878d3c9a8cf3426cc2112e1","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/234B","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:217A","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"db5f69dac51899df77a9938c74dea7e8a06300eba54a9981001c3c1350e351bf","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/217A","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:29","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"8ee1c85803bc6b7fe112bb418ae799c5e2a6d942973069c2d4986b92ab051a5d","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/29","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[8]}}}},{"candidate":"8d9741194dd24793d7d80b37262fe536ea60a00a90b64f0992591af2406b8ee3","expected_status":"under_review","expected_payload":{"raw_text":"25. O dependente químico severo, comprovado por laudo pericial,\nque, para poder comprar substância entorpecente a fim de\nsatisfazer seu vício, pratica conduta descrita em tipo penal de\nfurto, poderá arguir em sua defesa excludente de\nA) ilicitude pela inexigibilidade de conduta diversa.\nB) tipicidade pela ausência de dolo.\nC) culpabilidade pela coação moral irresistível.\nD) culpabilidade pela inimputabilidade.\nE) ilicitude pelo estado de necessidade.","item_number":25,"source_pages":[8],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"25. O dependente químico severo, comprovado por laudo pericial,\nque, para poder comprar substância entorpecente a fim de\nsatisfazer seu vício, pratica conduta descrita em tipo penal de\nfurto, poderá arguir em sua defesa excludente de\nA) ilicitude pela inexigibilidade de conduta diversa.\nB) tipicidade pela ausência de dolo.\nC) culpabilidade pela coação moral irresistível.\nD) culpabilidade pela inimputabilidade.\nE) ilicitude pelo estado de necessidade.","item_number":25,"source_pages":[8],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/8d9741194dd24793d7d80b37262fe536ea60a00a90b64f0992591af2406b8ee3","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Dependência química e imputabilidade","observed_style":"caso_pratico","explanation":"Dependência não basta para inimputabilidade: é necessário demonstrar incapacidade de entendimento ou autodeterminação no momento do fato e aplicar a disciplina específica. A alternativa D descreve a categoria arguível, não uma isenção automática por laudo de dependência.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_pendente"],"primary_evidence":[{"reference":"cp:26","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"8d2ef957335c08b41a32bc326e9dd1e6a5b917264c50e2cfcd0b91eb2153fd01","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/26","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[8]}}}},{"candidate":"3bbd472b77be5c2a774fdd7f1194e4f40a3ebeef9361ef9e6832726032432fe5","expected_status":"under_review","expected_payload":{"raw_text":"26. O Ministério Público denunciou Joana, servidora ocupante de\nfunção de direção de determinada autarquia, por delito de\npeculato, mas com a incidência da causa de aumento de pena\nprevista no parágrafo segundo do art. 327 do Código Penal, in\nverbis: “A pena será aumentada da terça parte quando os\nautores dos crimes previstos neste Capítulo forem ocupantes\nde cargos em comissão ou de função de direção ou\nassessoramento de órgão da administração direta, sociedade\nde economia mista, empresa pública ou fundação instituída\npelo poder público.” Acerca do caso, assinale a alternativa\ncorreta.\nA) A incidência da causa de aumento está correta, pois as\nautarquias podem ser equiparadas a órgãos da administração\npública direta.\nB) A causa de aumento de pena descrita somente poderá incidir\nse Joana tiver se aproveitado de sua condição de diretora da\nautarquia para praticar o delito.\nC) Não incide a causa de aumento de pena, pois as autarquias\nnão foram mencionadas em referida causa de aumento e, com\nbase no princípio da legalidade, veda-se analogia in malam\npartem.\nD) O delito praticado por Joana não foi peculato, pois diretor de\nautarquia não se equipara a funcionário público para fins de\naplicação da lei penal.\nE) Não incide a causa de aumento de pena, pois estamos diante\nde uma lei penal excepcional, que apenas será aplicada\nsubsidiariamente, ou seja, quando não houver nenhuma lei\nespecífica.","item_number":26,"source_pages":[8],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"26. O Ministério Público denunciou Joana, servidora ocupante de\nfunção de direção de determinada autarquia, por delito de\npeculato, mas com a incidência da causa de aumento de pena\nprevista no parágrafo segundo do art. 327 do Código Penal, in\nverbis: “A pena será aumentada da terça parte quando os\nautores dos crimes previstos neste Capítulo forem ocupantes\nde cargos em comissão ou de função de direção ou\nassessoramento de órgão da administração direta, sociedade\nde economia mista, empresa pública ou fundação instituída\npelo poder público.” Acerca do caso, assinale a alternativa\ncorreta.\nA) A incidência da causa de aumento está correta, pois as\nautarquias podem ser equiparadas a órgãos da administração\npública direta.\nB) A causa de aumento de pena descrita somente poderá incidir\nse Joana tiver se aproveitado de sua condição de diretora da\nautarquia para praticar o delito.\nC) Não incide a causa de aumento de pena, pois as autarquias\nnão foram mencionadas em referida causa de aumento e, com\nbase no princípio da legalidade, veda-se analogia in malam\npartem.\nD) O delito praticado por Joana não foi peculato, pois diretor de\nautarquia não se equipara a funcionário público para fins de\naplicação da lei penal.\nE) Não incide a causa de aumento de pena, pois estamos diante\nde uma lei penal excepcional, que apenas será aplicada\nsubsidiariamente, ou seja, quando não houver nenhuma lei\nespecífica.","item_number":26,"source_pages":[8],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/3bbd472b77be5c2a774fdd7f1194e4f40a3ebeef9361ef9e6832726032432fe5","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Legalidade e majorante de funcionário público","observed_style":"caso_pratico","explanation":"O art. 327, §2º, enumera entidades e não menciona autarquia no texto transcrito. C invoca vedação de analogia desfavorável; a qualidade de funcionário público do caput não se confunde com o âmbito da majorante. Conferir a jurisprudência específica.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente"],"primary_evidence":[{"reference":"cp:1","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"d605a5ba095f97a83cc0a87544da7e7af8c66cff4dfc58f159dda1ca27099271","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/1","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:327","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"d705e78c73b6176e5d1bde9381a3971ad80b9b6f87548fafa73ef8aeec67a557","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/327","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[8]}}}},{"candidate":"cdbb95aaee754e20e708f1318402c660acf1b5dfd441255689b0ac8ffa26788a","expected_status":"under_review","expected_payload":{"raw_text":"27. Em relação ao lugar do crime, territorialidade e\nextraterritorialidade da lei penal, assinale a alternativa correta.\nA) Se a execução de um delito ocorrer em território nacional, mas\no resultado ocorrer em território estrangeiro, não é correto\nafirmar que tal delito ocorreu em território nacional.\nB) Ficam sujeitos à lei penal brasileira, embora cometidos no\nestrangeiro, independentemente de condições, os crimes\npraticados por brasileiro contra brasileiro ou estrangeiro\nresidente no Brasil.\nC) Se a execução de um delito ocorrer em território estrangeiro,\nmas o resultado ocorrer em território nacional, é correto afirmar\nque tal delito ocorreu em território nacional.\nD) Crime cometido no estrangeiro contra a vida ou liberdade do\nPresidente da República brasileiro está sujeito a lei penal\nbrasileira desde que o agente não tenha sido absolvido no\nestrangeiro.\nE) Não se consideram extensão do território nacional aeronaves\nprivadas a serviço do governo brasileiro em espaço aéreo\ncorrespondente a outro país.","item_number":27,"source_pages":[8],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"27. Em relação ao lugar do crime, territorialidade e\nextraterritorialidade da lei penal, assinale a alternativa correta.\nA) Se a execução de um delito ocorrer em território nacional, mas\no resultado ocorrer em território estrangeiro, não é correto\nafirmar que tal delito ocorreu em território nacional.\nB) Ficam sujeitos à lei penal brasileira, embora cometidos no\nestrangeiro, independentemente de condições, os crimes\npraticados por brasileiro contra brasileiro ou estrangeiro\nresidente no Brasil.\nC) Se a execução de um delito ocorrer em território estrangeiro,\nmas o resultado ocorrer em território nacional, é correto afirmar\nque tal delito ocorreu em território nacional.\nD) Crime cometido no estrangeiro contra a vida ou liberdade do\nPresidente da República brasileiro está sujeito a lei penal\nbrasileira desde que o agente não tenha sido absolvido no\nestrangeiro.\nE) Não se consideram extensão do território nacional aeronaves\nprivadas a serviço do governo brasileiro em espaço aéreo\ncorrespondente a outro país.","item_number":27,"source_pages":[8],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/cdbb95aaee754e20e708f1318402c660acf1b5dfd441255689b0ac8ffa26788a","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Lugar do crime e ubiquidade","observed_style":"caso_pratico","explanation":"O art. 6º considera ação/omissão e produção ou resultado esperado. C aplica o critério ao resultado no Brasil; distinguir da extraterritorialidade condicionada do art. 7º.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo"],"primary_evidence":[{"reference":"cp:5","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"c85140943411d6343bfa006dbcb58102d1fcbecc317b43f4654052671095c4f0","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/5","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:6","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"e2a1f62ecd2d21b3b958caea359f498c203ddc54240c5a0bc2d73eb965457906","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/6","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:7","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"d1391d96c09b76d25d294adb2d6d459525553eb43e15af754ab2ec6afe056d18","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/7","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[8]}}}},{"candidate":"32d4ad13f965a6d5956f3c09b277c205f01d7e1308077d52839fdb0c4b736791","expected_status":"under_review","expected_payload":{"raw_text":"28. Em 10/1/2017, Robson praticou delito previsto na lei A, cuja\npena era de reclusão de 3 a 6 anos. Em 30/4/2019, a lei A foi\nrevogada pela lei B, que passou a prever pena de 1 a 3 anos\nde reclusão para a conduta praticada por Robson. Ocorre que,\nem 20/5/2020, entrou em vigor a lei C, revogando a lei B e\npassando a atribuir à conduta praticada por Robson pena de\nreclusão de 2 a 4 anos.\nConsidere que Robson foi denunciado pelo delito em\n30/5/2020 e, na data de hoje, ele está sendo sentenciado.\nNessa hipótese, é correto afirmar que\nA) será aplicada a Robson a lei A, por ser aquela em vigor no dia\nde sua conduta.\nB) será aplicada a Robson a lei B, por ser a mais benéfica.\nC) será aplicada a Robson a lei C, por ser a mais recente, que\nrevogou as demais leis anteriores.\nD) poderão ser aplicadas a lei A ou a lei C; a primeira porque era\na lei em vigor no dia da conduta e a segunda porque é a lei\nmais recente. A escolha ficará a critério do juiz, que deverá\noptar pela mais favorável ao caso concreto.\nE) será aplicada a Robson a lei C, não só porque é a mais\nrecente, mas também porque é mais benéfica se comparada à\nlei A, que vigorava no dia da conduta.","item_number":28,"source_pages":[9],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"28. Em 10/1/2017, Robson praticou delito previsto na lei A, cuja\npena era de reclusão de 3 a 6 anos. Em 30/4/2019, a lei A foi\nrevogada pela lei B, que passou a prever pena de 1 a 3 anos\nde reclusão para a conduta praticada por Robson. Ocorre que,\nem 20/5/2020, entrou em vigor a lei C, revogando a lei B e\npassando a atribuir à conduta praticada por Robson pena de\nreclusão de 2 a 4 anos.\nConsidere que Robson foi denunciado pelo delito em\n30/5/2020 e, na data de hoje, ele está sendo sentenciado.\nNessa hipótese, é correto afirmar que\nA) será aplicada a Robson a lei A, por ser aquela em vigor no dia\nde sua conduta.\nB) será aplicada a Robson a lei B, por ser a mais benéfica.\nC) será aplicada a Robson a lei C, por ser a mais recente, que\nrevogou as demais leis anteriores.\nD) poderão ser aplicadas a lei A ou a lei C; a primeira porque era\na lei em vigor no dia da conduta e a segunda porque é a lei\nmais recente. A escolha ficará a critério do juiz, que deverá\noptar pela mais favorável ao caso concreto.\nE) será aplicada a Robson a lei C, não só porque é a mais\nrecente, mas também porque é mais benéfica se comparada à\nlei A, que vigorava no dia da conduta.","item_number":28,"source_pages":[9],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"B","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/32d4ad13f965a6d5956f3c09b277c205f01d7e1308077d52839fdb0c4b736791","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Lei intermediária mais benéfica","observed_style":"caso_pratico","explanation":"A lei B tem a menor pena dentre as três e pode ter eficácia benéfica mesmo revogada pela C. CP 2 impede selecionar apenas a lei da ação ou a lei da sentença sem comparação global.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","marco_temporal_obrigatorio"],"primary_evidence":[{"reference":"cp:2","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"a9035113fb07336a444ee65a4b703246b78e8f43e98c44c43e4cb3aed7e69a37","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/2","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[9]}}}},{"candidate":"33dbf9283c83447a7ceb8a04fd765557ffa490119935c66cde4aa6aa48725bdd","expected_status":"under_review","expected_payload":{"raw_text":"29. Maria Luísa praticou delito de tráfico de drogas, na modalidade\n“manter em depósito”, bem como delito de associação para o\ntráfico, durante o período de 9/10/2005 a 4/8/2007. Presa em\nflagrante no dia 4/8/2007, foi denunciada como incursa nas\npenas dos artigos 33 e 35 da Lei 11.343/2006.\nNessa hipótese, assinale a alternativa correta levando em\nconta o entendimento dos tribunais superiores sobre o tema.\nA) Não se aplica a Lei 11.343/2006, e sim a Lei 6.368/1976, por\nser mais benéfica se comparada à Lei 11.343/2006.\nB) O juiz poderá combinar as Leis 11.343/2006 e 6.368/1976,\npara aplicar as regras mais favoráveis de cada uma das leis\nao caso concreto.\nC) Não poderá haver combinação de leis, mesmo se esta se\nmostrar medida mais favorável à ré. O que se deve fazer é\naplicar o critério do caso concreto e observar qual das leis é\nmais favorável à situação da ré como um todo.\nD) Em relação ao delito de tráfico de drogas, aplica-se a Lei\n6.368/1976, que tinha previsão de pena menor. Todavia, em\nrelação ao delito de associação para o tráfico, aplica-se a Lei\n11.343/2006, que, embora possua pena igual à descrita na lei\nanterior, é mais nova e, portanto, prevalece.\nE) Aplica-se a Lei 11.343/2006, mesmo sendo mais gravosa se\ncomparada à Lei 6.368/1976, pois os delitos em análise são\ncrimes permanentes.","item_number":29,"source_pages":[9],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"29. Maria Luísa praticou delito de tráfico de drogas, na modalidade\n“manter em depósito”, bem como delito de associação para o\ntráfico, durante o período de 9/10/2005 a 4/8/2007. Presa em\nflagrante no dia 4/8/2007, foi denunciada como incursa nas\npenas dos artigos 33 e 35 da Lei 11.343/2006.\nNessa hipótese, assinale a alternativa correta levando em\nconta o entendimento dos tribunais superiores sobre o tema.\nA) Não se aplica a Lei 11.343/2006, e sim a Lei 6.368/1976, por\nser mais benéfica se comparada à Lei 11.343/2006.\nB) O juiz poderá combinar as Leis 11.343/2006 e 6.368/1976,\npara aplicar as regras mais favoráveis de cada uma das leis\nao caso concreto.\nC) Não poderá haver combinação de leis, mesmo se esta se\nmostrar medida mais favorável à ré. O que se deve fazer é\naplicar o critério do caso concreto e observar qual das leis é\nmais favorável à situação da ré como um todo.\nD) Em relação ao delito de tráfico de drogas, aplica-se a Lei\n6.368/1976, que tinha previsão de pena menor. Todavia, em\nrelação ao delito de associação para o tráfico, aplica-se a Lei\n11.343/2006, que, embora possua pena igual à descrita na lei\nanterior, é mais nova e, portanto, prevalece.\nE) Aplica-se a Lei 11.343/2006, mesmo sendo mais gravosa se\ncomparada à Lei 6.368/1976, pois os delitos em análise são\ncrimes permanentes.","item_number":29,"source_pages":[9],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/33dbf9283c83447a7ceb8a04fd765557ffa490119935c66cde4aa6aa48725bdd","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Crime permanente e sucessão de leis","observed_style":"caso_pratico","explanation":"O caso situa permanência durante a entrada em vigor da lei nova. A tese E depende também da súmula do STF sobre cessação de permanência e não se confunde com combinação de leis para um fato instantâneo.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes","marco_temporal_obrigatorio"],"primary_evidence":[{"reference":"cp:4","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"e3daa01c71114002c26e135186a6e5e886e10dc0db069b6a6b2f8814a93132c0","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/4","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[9]}}}},{"candidate":"9a17b8fdc501cfff412081bfbfe7ff40e49bcc4222c7aeb99f12a55d324574bd","expected_status":"under_review","expected_payload":{"raw_text":"30. Marcelo importou substância entorpecente, classificada como\ndroga e, portanto, proscrita pela lei penal brasileira e seus\ncomplementos normativos.\nNessa hipótese, é correto afirmar que a responsabilidade\npenal de Marcelo será pelo delito de\nA) tráfico de drogas, apenas.\nB) contrabando, apenas, porque importou mercadoria proibida.\nC) contrabando, em concurso formal com delito de tráfico de\ndrogas.\nD) contrabando, tráfico de drogas e associação para o tráfico, em\nconcurso formal de delitos.\nE) tráfico de drogas e delito de contrabando, mas responderá\napenas pelo primeiro, pois o segundo ficará absorvido por\naquele.","item_number":30,"source_pages":[9],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"30. Marcelo importou substância entorpecente, classificada como\ndroga e, portanto, proscrita pela lei penal brasileira e seus\ncomplementos normativos.\nNessa hipótese, é correto afirmar que a responsabilidade\npenal de Marcelo será pelo delito de\nA) tráfico de drogas, apenas.\nB) contrabando, apenas, porque importou mercadoria proibida.\nC) contrabando, em concurso formal com delito de tráfico de\ndrogas.\nD) contrabando, tráfico de drogas e associação para o tráfico, em\nconcurso formal de delitos.\nE) tráfico de drogas e delito de contrabando, mas responderá\napenas pelo primeiro, pois o segundo ficará absorvido por\naquele.","item_number":30,"source_pages":[9],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"A","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/9a17b8fdc501cfff412081bfbfe7ff40e49bcc4222c7aeb99f12a55d324574bd","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Especialidade entre tráfico e contrabando","observed_style":"caso_pratico","explanation":"A alternativa A trabalha a lei especial de drogas para a importação da substância. Não acrescentar associação para o tráfico sem descrição de vínculo associativo; conferir os tipos especiais e a técnica de conflito aparente.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_pendente"],"primary_evidence":[{"reference":"cp:12","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"0930efac6ba3b4e87121a0d0f4a6a4e392f7c8113a40b1313bb94165513ba13c","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/12","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[9]}}}},{"candidate":"12f4e2ea09cbb529eac061a4ad4530749ff4f4feefa53b3397230d7fdc43e2ff","expected_status":"under_review","expected_payload":{"raw_text":"31. Segundo a teoria tripartite, majoritariamente adotada, o delito é\ncomposto de fato típico, ilicitude e culpabilidade. São elementos\ndo fato típico:\nA) tipicidade, ilicitude, imputabilidade.\nB) conduta dolosa ou culposa, ausência de situações justificantes,\nimputabilidade.\nC) conduta dolosa ou culposa, resultado, nexo causal e tipicidade.\nD) tipicidade, ausência de situações justificantes, culpabilidade.\nE) tipicidade formal, tipicidade material, ausência de situações\njustificantes e imputabilidade.","item_number":31,"source_pages":[9],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"31. Segundo a teoria tripartite, majoritariamente adotada, o delito é\ncomposto de fato típico, ilicitude e culpabilidade. São elementos\ndo fato típico:\nA) tipicidade, ilicitude, imputabilidade.\nB) conduta dolosa ou culposa, ausência de situações justificantes,\nimputabilidade.\nC) conduta dolosa ou culposa, resultado, nexo causal e tipicidade.\nD) tipicidade, ausência de situações justificantes, culpabilidade.\nE) tipicidade formal, tipicidade material, ausência de situações\njustificantes e imputabilidade.","item_number":31,"source_pages":[9],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/12f4e2ea09cbb529eac061a4ad4530749ff4f4feefa53b3397230d7fdc43e2ff","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Elementos do fato típico","observed_style":"teoria_doutrinaria","explanation":"A alternativa C usa a classificação doutrinária conduta, resultado, nexo e tipicidade. A exigência de resultado naturalístico varia conforme a espécie de delito; o resumo não deve sugerir que todo crime é material.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","doutrina_pendente"],"primary_evidence":[{"reference":"cp:13","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"f93da1ae56d777386c683c8afb2da2572e69534995e422855eca1c985fb5fd90","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/13","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:18","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"5ebdb6305fe25556cfc43e255327aaff15028ba069d1ba8f44a268d3e7966a62","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/18","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[9]}}}},{"candidate":"4eab75dd53273e2ee281d57b39571dc51a94c9db3b949971655bb890223b7889","expected_status":"under_review","expected_payload":{"raw_text":"32. Carolina é empregada doméstica na residência de Letícia e\nJorge e recebeu uma cópia da chave que dá acesso à casa de\nseus patrões. Todavia, o companheiro de Carolina, Ricardo,\naproveitando-se do fato de que a referida chave estava à vista e\nsem vigilância, fez uma cópia do objeto e utilizou essa cópia para\nentrar na casa de Letícia e Jorge e, de lá, subtraiu bens e\nvalores, que totalizaram um prejuízo de R$100.000,00 às\nvítimas.\nNessa hipótese, é correto afirmar que Carolina\nA) poderá responder como partícipe do furto praticado por\nRicardo.\nB) poderá responder como coautora do furto praticado por\nRicardo.\nC) pode ser classificada como autora mediata do furto.\nD) poderá responder culposamente pelo delito de furto.\nE) não praticou crime algum.","item_number":32,"source_pages":[9],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"32. Carolina é empregada doméstica na residência de Letícia e\nJorge e recebeu uma cópia da chave que dá acesso à casa de\nseus patrões. Todavia, o companheiro de Carolina, Ricardo,\naproveitando-se do fato de que a referida chave estava à vista e\nsem vigilância, fez uma cópia do objeto e utilizou essa cópia para\nentrar na casa de Letícia e Jorge e, de lá, subtraiu bens e\nvalores, que totalizaram um prejuízo de R$100.000,00 às\nvítimas.\nNessa hipótese, é correto afirmar que Carolina\nA) poderá responder como partícipe do furto praticado por\nRicardo.\nB) poderá responder como coautora do furto praticado por\nRicardo.\nC) pode ser classificada como autora mediata do furto.\nD) poderá responder culposamente pelo delito de furto.\nE) não praticou crime algum.","item_number":32,"source_pages":[9],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/4eab75dd53273e2ee281d57b39571dc51a94c9db3b949971655bb890223b7889","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Vínculo subjetivo e furto culposo","observed_style":"caso_pratico","explanation":"O relato não descreve adesão da empregada ao plano do companheiro. Sem dolo de contribuição ou tipo culposo específico de furto, a responsabilização não decorre da mera falta de vigilância da chave.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo"],"primary_evidence":[{"reference":"cp:18","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"5ebdb6305fe25556cfc43e255327aaff15028ba069d1ba8f44a268d3e7966a62","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/18","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:29","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"8ee1c85803bc6b7fe112bb418ae799c5e2a6d942973069c2d4986b92ab051a5d","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/29","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:155","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"81e34f539a7bdaed2d722cbc54f8e8d98c9ca784581b093671e88a92bee9ee67","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/155","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[9]}}}},{"candidate":"7f82b63179b431abf507b784385e58d55880bf2d68f0039e8ecac92f6eabcec6","expected_status":"under_review","expected_payload":{"raw_text":"33. Robson foi denunciado pelo delito de roubo com emprego de\narma de fogo. Durante o processo foi requerida a prisão\npreventiva pelo Ministério Público, mas o magistrado, ao invés\nde decretar a prisão cautelar, de modo substitutivo, determinou\no recolhimento domiciliar noturno de Robson, sendo certo que\na medida cautelar foi cumprida pelo período de 1 ano e 6\nmeses. Ao final da instrução criminal, Robson restou\ncondenado a 7 anos de reclusão em regime inicial semiaberto.\nA condenação transitou definitivamente em julgado e Robson\ncomeçou o cumprimento da pena.\nNessa hipótese, assinale a alternativa correta, tendo em vista\no entendimento dos tribunais superiores acerca do tema.\nA) Embora Robson tenha cumprido medida cautelar de\nrecolhimento domiciliar noturno durante 1 ano e 6 meses, esse\nperíodo não poderá ser descontado da pena final imposta\nporque a detração é instituto apenas aplicável às prisões\ncautelares, não cabendo falar em analogia em direito penal\ncom base no princípio da legalidade.\nB) A defesa de Robson poderá requerer ao juiz da Vara de\nExecuções Penais o benefício da remição da pena,\npermitindo-se que o tempo em que o condenado esteve\nrespondendo ao processo e em recolhimento domiciliar\nnoturno seja descontado do tempo total de pena imposta na\ncondenação.\nC) Embora Robson tenha cumprido medida cautelar de\nrecolhimento domiciliar noturno durante 1 ano e 6 meses, esse\nperíodo não poderá ser descontado da pena final imposta\nporque a remição é instituto apenas aplicável às prisões\ncautelares, não cabendo falar em analogia em direito penal\ncom base no princípio da legalidade.\nD) A defesa de Robson poderá requerer dois benefícios\ndecorrentes do tempo em que o condenado cumpriu medida\ncautelar de recolhimento domiciliar noturno, quais sejam:\ndetração e remição, sendo certo que ambos possuem previsão\nlegal à hipótese.\nE) A defesa de Robson poderá requerer ao juiz da Vara de\nExecuções Penais o benefício da detração penal analógica,\npermitindo-se que o tempo em que ficou cumprindo medida\ncautelar de recolhimento domiciliar noturno seja descontado\ndo tempo de pena total imposta na condenação.","item_number":33,"source_pages":[10],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"33. Robson foi denunciado pelo delito de roubo com emprego de\narma de fogo. Durante o processo foi requerida a prisão\npreventiva pelo Ministério Público, mas o magistrado, ao invés\nde decretar a prisão cautelar, de modo substitutivo, determinou\no recolhimento domiciliar noturno de Robson, sendo certo que\na medida cautelar foi cumprida pelo período de 1 ano e 6\nmeses. Ao final da instrução criminal, Robson restou\ncondenado a 7 anos de reclusão em regime inicial semiaberto.\nA condenação transitou definitivamente em julgado e Robson\ncomeçou o cumprimento da pena.\nNessa hipótese, assinale a alternativa correta, tendo em vista\no entendimento dos tribunais superiores acerca do tema.\nA) Embora Robson tenha cumprido medida cautelar de\nrecolhimento domiciliar noturno durante 1 ano e 6 meses, esse\nperíodo não poderá ser descontado da pena final imposta\nporque a detração é instituto apenas aplicável às prisões\ncautelares, não cabendo falar em analogia em direito penal\ncom base no princípio da legalidade.\nB) A defesa de Robson poderá requerer ao juiz da Vara de\nExecuções Penais o benefício da remição da pena,\npermitindo-se que o tempo em que o condenado esteve\nrespondendo ao processo e em recolhimento domiciliar\nnoturno seja descontado do tempo total de pena imposta na\ncondenação.\nC) Embora Robson tenha cumprido medida cautelar de\nrecolhimento domiciliar noturno durante 1 ano e 6 meses, esse\nperíodo não poderá ser descontado da pena final imposta\nporque a remição é instituto apenas aplicável às prisões\ncautelares, não cabendo falar em analogia em direito penal\ncom base no princípio da legalidade.\nD) A defesa de Robson poderá requerer dois benefícios\ndecorrentes do tempo em que o condenado cumpriu medida\ncautelar de recolhimento domiciliar noturno, quais sejam:\ndetração e remição, sendo certo que ambos possuem previsão\nlegal à hipótese.\nE) A defesa de Robson poderá requerer ao juiz da Vara de\nExecuções Penais o benefício da detração penal analógica,\npermitindo-se que o tempo em que ficou cumprindo medida\ncautelar de recolhimento domiciliar noturno seja descontado\ndo tempo de pena total imposta na condenação.","item_number":33,"source_pages":[10],"answer_in_official_document":"E","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/7f82b63179b431abf507b784385e58d55880bf2d68f0039e8ecac92f6eabcec6","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Detração de recolhimento domiciliar","observed_style":"caso_pratico","explanation":"O gabarito E refere-se à detração, não remição. A conversão de horas de recolhimento em tempo de pena e as condições do abatimento dependem da tese atual do STJ; não descontar integralmente 18 meses sem apurar as restrições.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente"],"primary_evidence":[{"reference":"cp:42","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"eaca720c084924b0c48e21d699e7740177c59a3637e535717e0526639567519e","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/42","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[10]}}}},{"candidate":"aef95dabb098030b63e861214e225682e47474d88d65dad3e390431a6ae3c51c","expected_status":"under_review","expected_payload":{"raw_text":"34. Considere que Fernando, penalmente imputável de 25 anos,\ncom consciência e vontade, instigue e induza Camilo,\npenalmente inimputável de 15 anos, a praticar ato infracional\nanálogo ao delito de roubo. Relativamente à responsabilização\nde Fernando no tocante ao roubo, assinale a alternativa\ncorreta.\nA) Responderá como coautor de delito de roubo.\nB) Não responderá criminalmente pelo roubo.\nC) Responderá por roubo impróprio praticado em concurso de\npessoas.\nD) Responderá como partícipe de delito de roubo.\nE) Responderá por roubo com a incidência de qualificadora.","item_number":34,"source_pages":[10],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"34. Considere que Fernando, penalmente imputável de 25 anos,\ncom consciência e vontade, instigue e induza Camilo,\npenalmente inimputável de 15 anos, a praticar ato infracional\nanálogo ao delito de roubo. Relativamente à responsabilização\nde Fernando no tocante ao roubo, assinale a alternativa\ncorreta.\nA) Responderá como coautor de delito de roubo.\nB) Não responderá criminalmente pelo roubo.\nC) Responderá por roubo impróprio praticado em concurso de\npessoas.\nD) Responderá como partícipe de delito de roubo.\nE) Responderá por roubo com a incidência de qualificadora.","item_number":34,"source_pages":[10],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/aef95dabb098030b63e861214e225682e47474d88d65dad3e390431a6ae3c51c","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Participação com executor inimputável","observed_style":"caso_pratico","explanation":"A inimputabilidade do executor não torna, automaticamente, todo indutor autor mediato. D exige examinar domínio do fato e atuação do adolescente; distinguir participação de utilização de instrumento sem autonomia. Falta fonte doutrinária/judicial específica.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","doutrina_e_jurisprudencia_pendentes"],"primary_evidence":[{"reference":"cp:27","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"153be93de752bfe8a518b3226e6585f97ae2faf1d62519c8e5fbbca60784c16c","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/27","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:29","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"8ee1c85803bc6b7fe112bb418ae799c5e2a6d942973069c2d4986b92ab051a5d","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/29","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[10]}}}},{"candidate":"6123717e6c63bdcfeb9b6d2b108f682d0d041157cbebafcdc999da977eb236b6","expected_status":"under_review","expected_payload":{"raw_text":"35. Vinícius sofre de sonambulismo desde a mais tenra idade.\nCerta noite, durante o sono, Vinícius, em estado de\ninconsciência, se levanta e se dirige até o escritório de sua\ncasa e pega uma tesoura na gaveta. Nesse momento, sua\nesposa toca em seu ombro para levá-lo de volta à cama,\nocasião em que Vinícius, ainda sonâmbulo, se vira e desfere\ncinco golpes com a tesoura em sua esposa, na altura do\nabdômen. Ato contínuo, Vinícius retorna para o quarto e\ncontinua seu sono, enquanto sua esposa cai inconsciente e\nmorre minutos depois em virtude da excessiva perda de\nsangue.\nNessa hipótese, é correto afirmar que Vinícius\nA) deve responder por delito de homicídio culposo.\nB) deve responder por delito de homicídio doloso, praticado com\ndolo eventual.\nC) não praticou crime, pois o estado de inconsciência exclui a\nculpabilidade pela inexigibilidade de conduta diversa.\nD) não praticou crime, pois o estado de inconsciência exclui a\nconduta, por ausência de voluntariedade no movimento.\nE) deve responder por delito de homicídio preterdoloso.","item_number":35,"source_pages":[10],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"35. Vinícius sofre de sonambulismo desde a mais tenra idade.\nCerta noite, durante o sono, Vinícius, em estado de\ninconsciência, se levanta e se dirige até o escritório de sua\ncasa e pega uma tesoura na gaveta. Nesse momento, sua\nesposa toca em seu ombro para levá-lo de volta à cama,\nocasião em que Vinícius, ainda sonâmbulo, se vira e desfere\ncinco golpes com a tesoura em sua esposa, na altura do\nabdômen. Ato contínuo, Vinícius retorna para o quarto e\ncontinua seu sono, enquanto sua esposa cai inconsciente e\nmorre minutos depois em virtude da excessiva perda de\nsangue.\nNessa hipótese, é correto afirmar que Vinícius\nA) deve responder por delito de homicídio culposo.\nB) deve responder por delito de homicídio doloso, praticado com\ndolo eventual.\nC) não praticou crime, pois o estado de inconsciência exclui a\nculpabilidade pela inexigibilidade de conduta diversa.\nD) não praticou crime, pois o estado de inconsciência exclui a\nconduta, por ausência de voluntariedade no movimento.\nE) deve responder por delito de homicídio preterdoloso.","item_number":35,"source_pages":[10],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/6123717e6c63bdcfeb9b6d2b108f682d0d041157cbebafcdc999da977eb236b6","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Conduta e sonambulismo","observed_style":"caso_pratico","explanation":"O relato afirma estado de inconsciência durante os movimentos. D corresponde à falta de voluntariedade da conduta; não deslocar a explicação para inexigibilidade de conduta diversa ou dolo eventual sem dados adicionais.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","doutrina_pendente"],"primary_evidence":[{"reference":"cp:13","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"f93da1ae56d777386c683c8afb2da2572e69534995e422855eca1c985fb5fd90","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/13","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:18","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"5ebdb6305fe25556cfc43e255327aaff15028ba069d1ba8f44a268d3e7966a62","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/18","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[10]}}}},{"candidate":"9bc92366895ab2a0639273ce3b17f66b10a2a524d01392cb75f41f3cb40ecbb8","expected_status":"under_review","expected_payload":{"raw_text":"36. Raíssa, penalmente imputável de 20 anos, reside com a mãe,\nLourdes, de 45 anos. Aproveitando-se da desatenção de sua\ngenitora, Raíssa subtrai da carteira da mãe a quantia de\nR$5.000,00 (cinco mil reais). Nessa hipótese, assinale a\nalternativa correta.\nA) Raíssa responderá por delito de furto, mas com causa de\ndiminuição de pena.\nB) Raíssa responderá por delito de apropriação indébita,\nincidindo agravante de delito praticado contra ascendente.\nC) Raíssa é isenta de pena, incidindo hipótese de escusa\nabsolutória.\nD) Raíssa responderá por delito de estelionato, incidindo\nagravante de delito praticado contra ascendente.\nE) A escusa absolutória aplica-se a todos os delitos patrimoniais,\nmas não impede eventual incidência de circunstância\nagravante de delito praticado contra ascendente.","item_number":36,"source_pages":[11],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"36. Raíssa, penalmente imputável de 20 anos, reside com a mãe,\nLourdes, de 45 anos. Aproveitando-se da desatenção de sua\ngenitora, Raíssa subtrai da carteira da mãe a quantia de\nR$5.000,00 (cinco mil reais). Nessa hipótese, assinale a\nalternativa correta.\nA) Raíssa responderá por delito de furto, mas com causa de\ndiminuição de pena.\nB) Raíssa responderá por delito de apropriação indébita,\nincidindo agravante de delito praticado contra ascendente.\nC) Raíssa é isenta de pena, incidindo hipótese de escusa\nabsolutória.\nD) Raíssa responderá por delito de estelionato, incidindo\nagravante de delito praticado contra ascendente.\nE) A escusa absolutória aplica-se a todos os delitos patrimoniais,\nmas não impede eventual incidência de circunstância\nagravante de delito praticado contra ascendente.","item_number":36,"source_pages":[11],"answer_in_official_document":"C","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/9bc92366895ab2a0639273ce3b17f66b10a2a524d01392cb75f41f3cb40ecbb8","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Escusa absolutória patrimonial","observed_style":"caso_pratico","explanation":"O art. 181 contempla descendente contra ascendente, ressalvadas as exceções do art. 183. O caso informa mãe de 45 anos e ausência de violência; não generalizar a isenção para todos os crimes patrimoniais.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo"],"primary_evidence":[{"reference":"cp:181","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"a7ecdd58f485746040094c4920464a4767a092f398c2bfbee50323aa2948adbc","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/181","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:183","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"32e64271c11a54641df1d6ed768ea2a0012d164f26fc97d42a2c94349e26c65a","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/183","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[11]}}}},{"candidate":"efce7bd288053a56ed4cd6119518e4729d41f860255ea12ca04f72e2e55f000d","expected_status":"under_review","expected_payload":{"raw_text":"37. A Lei 11.343/06 – Lei de Drogas – revogou a antiga Lei de\nEntorpecentes – 6.368/76 – e trouxe consigo uma das grandes\ne polêmicas inovações: a retirada da pena de prisão para o\ncrime de uso de drogas, atualmente previsto no artigo 28 da\nLei 11.343/06. O Superior Tribunal de Justiça possui um\ngrande acervo jurisprudencial sobre o tema. Assinale a\nafirmativa que está em DESACORDO com a jurisprudência do\nSTJ.\nA) A inobservância do art. 55 da Lei 11.343/2006, que determina\no recebimento da denúncia após a apresentação da defesa\nprévia, constitui nulidade relativa quando forem demonstrados\nos prejuízos suportados pela defesa.\nB) É prescindível a confecção do laudo toxicológico para\ncomprovar a materialidade da infração disciplinar e a natureza\nda substância encontrada com o apenado no interior de\nestabelecimento prisional.\nC) A falta da assinatura do perito criminal no laudo toxicológico é\nmera irregularidade que não tem o condão de anular o referido\nexame.\nD) As contravenções penais, puníveis com pena de prisão\nsimples, não geram reincidência, mostrando-se, portanto,\ndesproporcional que condenações anteriores pelo delito do art.\n28 da Lei 11.343/2006 configurem reincidência, uma vez que\nnão são puníveis com pena privativa de liberdade.\nE) É cabível a aplicação retroativa da Lei 11.343/2006, desde que\no resultado da incidência das suas disposições, na íntegra,\nseja mais favorável ao réu do que o advindo da aplicação da\nLei 6.368/1976, sendo vedada a combinação de leis.","item_number":37,"source_pages":[11],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"37. A Lei 11.343/06 – Lei de Drogas – revogou a antiga Lei de\nEntorpecentes – 6.368/76 – e trouxe consigo uma das grandes\ne polêmicas inovações: a retirada da pena de prisão para o\ncrime de uso de drogas, atualmente previsto no artigo 28 da\nLei 11.343/06. O Superior Tribunal de Justiça possui um\ngrande acervo jurisprudencial sobre o tema. Assinale a\nafirmativa que está em DESACORDO com a jurisprudência do\nSTJ.\nA) A inobservância do art. 55 da Lei 11.343/2006, que determina\no recebimento da denúncia após a apresentação da defesa\nprévia, constitui nulidade relativa quando forem demonstrados\nos prejuízos suportados pela defesa.\nB) É prescindível a confecção do laudo toxicológico para\ncomprovar a materialidade da infração disciplinar e a natureza\nda substância encontrada com o apenado no interior de\nestabelecimento prisional.\nC) A falta da assinatura do perito criminal no laudo toxicológico é\nmera irregularidade que não tem o condão de anular o referido\nexame.\nD) As contravenções penais, puníveis com pena de prisão\nsimples, não geram reincidência, mostrando-se, portanto,\ndesproporcional que condenações anteriores pelo delito do art.\n28 da Lei 11.343/2006 configurem reincidência, uma vez que\nnão são puníveis com pena privativa de liberdade.\nE) É cabível a aplicação retroativa da Lei 11.343/2006, desde que\no resultado da incidência das suas disposições, na íntegra,\nseja mais favorável ao réu do que o advindo da aplicação da\nLei 6.368/1976, sendo vedada a combinação de leis.","item_number":37,"source_pages":[11],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"B","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/efce7bd288053a56ed4cd6119518e4729d41f860255ea12ca04f72e2e55f000d","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Drogas, prova e jurisprudência temporal","observed_style":"jurisprudencia_em_alternativas","explanation":"B é a resposta histórica do comando em desacordo. O item reúne materialidade toxicológica, nulidades, reincidência e lei no tempo; exige confirmação das teses atuais, inclusive do impacto de decisões posteriores sobre porte para uso. Não certificar o conjunto só com Lei 11.343.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_especial_e_jurisprudencia_pendentes"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[11]}}}},{"candidate":"9082bcbec729eed0e6acc2cfde82b5716b33701420756a11e959162a89ba786b","expected_status":"under_review","expected_payload":{"raw_text":"38. O crime de furto é descrito no artigo 155 como a “subtração de\ncoisa alheia móvel para si ou para outrem”. A doutrina e a\njurisprudência divergem sobre o momento consumativo do\nfurto, sendo certo que existem quatro teorias sobre o tema. O\nSuperior Tribunal de Justiça já teve oportunidade de se\nmanifestar sobre esse assunto.\nAssinale a alternativa que demonstre a teoria adotada por esse\nTribunal Superior.\nA) furtatio\nB) contrectacio\nC) ilatio\nD) apprehensio (amotio)\nE) ablatio","item_number":38,"source_pages":[11],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"38. O crime de furto é descrito no artigo 155 como a “subtração de\ncoisa alheia móvel para si ou para outrem”. A doutrina e a\njurisprudência divergem sobre o momento consumativo do\nfurto, sendo certo que existem quatro teorias sobre o tema. O\nSuperior Tribunal de Justiça já teve oportunidade de se\nmanifestar sobre esse assunto.\nAssinale a alternativa que demonstre a teoria adotada por esse\nTribunal Superior.\nA) furtatio\nB) contrectacio\nC) ilatio\nD) apprehensio (amotio)\nE) ablatio","item_number":38,"source_pages":[11],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"D","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/9082bcbec729eed0e6acc2cfde82b5716b33701420756a11e959162a89ba786b","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Consumação do furto","observed_style":"jurisprudencia_em_alternativas","explanation":"O gabarito D aponta apprehensio/amotio e exige o precedente do STJ sobre inversão da posse, ainda que breve. Não exigir posse mansa ou retirada para local seguro sem conferir a tese atual.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","jurisprudencia_pendente"],"primary_evidence":[{"reference":"cp:155","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"81e34f539a7bdaed2d722cbc54f8e8d98c9ca784581b093671e88a92bee9ee67","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/155","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[11]}}}},{"candidate":"51efbee47f0045d2e693ce758ce45dd74eb22f55144007c2260a9ca937b1aea0","expected_status":"under_review","expected_payload":{"raw_text":"39. Wilson, engenheiro civil, está construindo um edifício em\nregião pantanosa. Durante a obra, é alertado pelo seu mestre\nde obras acerca da necessidade de criar uma fundação mais\nprofunda, já que o terreno onde o prédio está sendo construído\npossui leito de rocha mais profundo que o usual. Do contrário,\nsegundo o alerta feito, a construção poderia adernar e chegar\na cair, ocasionando a morte de pessoas. Levando em conta os\ncustos da construção e sem se importar com as\nconsequências, Wilson decide não seguir as orientações do\nmestre de obras e leva a obra adiante. Infelizmente, dois anos\napós a inauguração do prédio, ele desaba e seis pessoas\nmorrem.\nNessa hipótese, é correto afirmar que Wilson\nA) deve responder por seis delitos de homicídio culposo,\npraticados com culpa consciente, em concurso formal de\ndelitos.\nB) deve responder por seis delitos de homicídio, praticados com\ndolo eventual, em concurso formal de delitos.\nC) deve responder por seis delitos de homicídio, praticados com\ndolo direto, em concurso material de delitos.\nD) não praticou crime algum, mas deverá responder na esfera\ncivil.\nE) deve responder por seis delitos de homicídio preterdoloso,\npraticados em concurso material de delitos.","item_number":39,"source_pages":[11],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"39. Wilson, engenheiro civil, está construindo um edifício em\nregião pantanosa. Durante a obra, é alertado pelo seu mestre\nde obras acerca da necessidade de criar uma fundação mais\nprofunda, já que o terreno onde o prédio está sendo construído\npossui leito de rocha mais profundo que o usual. Do contrário,\nsegundo o alerta feito, a construção poderia adernar e chegar\na cair, ocasionando a morte de pessoas. Levando em conta os\ncustos da construção e sem se importar com as\nconsequências, Wilson decide não seguir as orientações do\nmestre de obras e leva a obra adiante. Infelizmente, dois anos\napós a inauguração do prédio, ele desaba e seis pessoas\nmorrem.\nNessa hipótese, é correto afirmar que Wilson\nA) deve responder por seis delitos de homicídio culposo,\npraticados com culpa consciente, em concurso formal de\ndelitos.\nB) deve responder por seis delitos de homicídio, praticados com\ndolo eventual, em concurso formal de delitos.\nC) deve responder por seis delitos de homicídio, praticados com\ndolo direto, em concurso material de delitos.\nD) não praticou crime algum, mas deverá responder na esfera\ncivil.\nE) deve responder por seis delitos de homicídio preterdoloso,\npraticados em concurso material de delitos.","item_number":39,"source_pages":[11],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"B","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/51efbee47f0045d2e693ce758ce45dd74eb22f55144007c2260a9ca937b1aea0","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Dolo eventual e concurso formal","observed_style":"caso_pratico","explanation":"A narrativa diz que o construtor prosseguiu sem se importar com as consequências após alerta. Isso sustenta a discussão de dolo eventual, mas não o presume de todo acidente ou infração técnica; conferir vínculo subjetivo e modalidade do concurso.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","doutrina_e_jurisprudencia_pendentes"],"primary_evidence":[{"reference":"cp:18","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"5ebdb6305fe25556cfc43e255327aaff15028ba069d1ba8f44a268d3e7966a62","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/18","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cp:70","title":"Código Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-2848-7-dezembro-1940-412868-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"57547f371c5dd6e609f453397d2098e3930876b03f7233096b0dff907832b3e4","excerpt_sha256":"5f8925868b28082225a1cfeedadd553587fcfded21543da4a3ec1b6678d934cc","excerpt_artifact":"fontes-e-excertos.json#/sources/cp/excerpts/70","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[11]}}}}]$idecan_review_batch$::jsonb) loop
    select * into stored from public.question_corpus_candidates where id=change->>'candidate' for update;
    if not found then raise exception 'Candidato não encontrado; aplique antes o acervo de 200 itens'; end if;
    if stored.content_status=change->>'next_status' and stored.payload=change->'next_payload' then continue; end if;
    if stored.content_status is distinct from change->>'expected_status'
      or stored.payload is distinct from change->'expected_payload' then
      raise exception 'Revisão desatualizada: decisão existente preservada; recarregue o candidato';
    end if;
    if stored.content_status <> 'under_review' then raise exception 'Decisão anterior protegida'; end if;
    if change->'next_payload'->'raw_text' is distinct from stored.payload->'raw_text' then
      raise exception 'Extração original protegida';
    end if;
    if change->'next_payload' ? 'publication'
      or change#>>'{next_payload,individual_review,publication_approved}' is distinct from 'false' then
      raise exception 'Este lote não permite publicação';
    end if;
    insert into public.question_corpus_review_audit(candidate_id,previous_status,next_status,previous_payload,next_payload,reviewer_id)
    values(stored.id,stored.content_status,change->>'next_status',stored.payload,change->'next_payload',auth.uid());
    update public.question_corpus_candidates set content_status=change->>'next_status',payload=change->'next_payload' where id=stored.id;
  end loop;
end $review$;
commit;
-- reviewed significa parecer registrado, não autorização de publicação.
select s.title,c.content_status,count(*) as candidates
from public.question_corpus_sources s join public.question_corpus_candidates c on c.corpus_id=s.id
where s.id in ('56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe','a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d')
group by s.title,c.content_status order by s.title,c.content_status;
